<h1 class="h3 mb-3">Relatórios de vendas</h1><form class="card card-body mb-3" method="get"><input type="hidden" name="route" value="reports"><div class="row align-items-end"><div class="col-md-4"><label class="form-label">Data inicial</label><input class="form-control" type="date" name="de" value="<?= htmlspecialchars($from) ?>"></div><div class="col-md-4"><label class="form-label">Data final</label><input class="form-control" type="date" name="ate" value="<?= htmlspecialchars($to) ?>"></div><div class="col-md-4"><button class="btn btn-primary">Filtrar</button> <a class="btn btn-outline-secondary" href="index.php?route=reports">Limpar</a></div></div></form><div class="card"><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>Nº</th><th>Data</th><th>Cliente</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php $sum=0;foreach($sales as $s):if($s['status']==='finalizada')$sum+=(float)$s['total']; ?><tr><td>#<?= (int)$s['id'] ?></td><td><?= date('d/m/Y H:i',strtotime($s['criada_em'])) ?></td><td><?= htmlspecialchars($s['cliente']??'Consumidor') ?></td><td>R$ <?= number_format((float)$s['total'],2,',','.') ?></td><td><?= htmlspecialchars($s['status']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="index.php?route=sale-detail&id=<?= (int)$s['id'] ?>">Detalhes</a><?php if($s['status']==='finalizada'): ?> <form class="d-inline" method="post" action="index.php?route=sale-cancel" onsubmit="return confirm('Cancelar venda e devolver itens ao estoque?')"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$sales): ?><tr><td colspan="6" class="text-center">Nenhuma venda encontrada.</td></tr><?php endif; ?></tbody></table></div></div><p class="mt-3"><strong>Total de vendas finalizadas no filtro: R$ <?= number_format($sum,2,',','.') ?></strong></p>
